UPDATE house_races SET candidate1_name = 'Mary Gay Scanlon' WHERE state_code = 'PA' AND district = 5;

-- Check CA-1
SELECT state_code, district, candidate1_name, candidate1_party, candidate2_name, candidate2_party, status
FROM house_races WHERE state_code = 'CA' AND district = 1;

